import{_ as r,o as e,c as s,ah as b}from"./chunks/framework.DjU4PSOm.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"computer/Research/URA/daily/260730 온라인.md","filePath":"computer/Research/URA/daily/260730 온라인.md"}'),t={name:"computer/Research/URA/daily/260730 온라인.md"};function a(n,p,m,o,d,i){return e(),s("div",null,[...p[0]||(p[0]=[b("<p>빌드하고 실행하는 방법<br> make clean<br> make - 치면 빌드</p><p>Kbulid에서<br> config_nvmevirt_ssd를 주석처리를 꺼야됨</p><p>disk model csl virt 달려있는게 우리가 써야하는거<br> os에서는 서버 보드 m.투 슬로에 하나 물려있음?<br> m.to 디바이스로 실행하는데 실물로 하고있는데<br> nvmvert쓴다고 하면 실습 결과가 제대로 안나옴</p><p>디스크 모델이나 이런거 신경써야함<br> 물리 디스크 꼽으면 파일을 마운트를 해줘야함</p><p>마운트할떄는 여러문 벌트 폴더 만들어서 mnt만들어서 거기에 벌트하면 됨</p><p>sudo 뭐 하니까<br> 디바이스가 뜸 1n1 디바이스가 뜸..</p><p>/umount.sh<br> rmmod.sh</p><p>nvmv-debug써서 출력하면 된다..</p><p>sudo dmesg</p><p>fio하는법 스토리지 디바이스에 io를 때려 넣어줌 read write를 바꿔가면서<br> ![[fio_randwrite_command_example.png]]</p><p>이거는 나중에 llm도움 받아서 공부, fio공식 사이트 찾아보기<br> percentile 뽑아주는 옵션도 있다..<br> 지금은 disable lat 이런거 다 disable되어있는데 키면 된다<br> 나온거 기반으로 그림을 그려봐야한다</p><p>빌드하고 실행 모듈 설치 마운트해서 돌아가게 하는거<br> 언마운트 하고 리무브모듈해서 실험 끝내고<br> fio기본 스크립트는 공유</p><p>런타임은 초단위<br> 레이턴시 파일 기반으로 그림으로 찍는거는 llm한테 물어보면 된다</p><p>과제 진행<br> 마운트 언마운트하는건 공유하면 상황에 맞게 바꿔 사용해야한다.</p><p>첫 과제는 gc<br> gc자체는 호스트에서 보내는게 아니라 디바이스 내부에서 알아서 진행<br> 디버그 메세지를 써서 진행함을 알수있는데 실제로는 그렇지 않음</p><p>이번 목표는 fio를 돌려서 gc가 발생되는지 체크<br> 발생되는것 같다 하면?<br> 어디서 gc라는게 페이지 카피를 하니까 뭐가</p><p>어디서 퍼포먼스가 밀리는 것 같다 어떤걸 중심으로 해야겠다 생각<br> gc발생했다면 설명할만한 그림</p><p>잘가는데 팍 뛴다 - &gt; 이거 gc아닌가 의심해볼 수 있을 거다..</p><p>벌트랑 fio써서 실험 진행<br> gc관련된 코드 뜯어보기<br> gc발생했어라고 설명할 부분을 그림이나 이런걸로 자료 준비</p><p>ssd config 파일을 봐야한다<br> ssd config에서<br> base ssd 삼성 970프로<br> 우리가 k빌드에서 컨벤셔널 ftl쓰는거로 되어있음<br> 실험 돌릴떄 쓰는거 4인데 1로 바꾼거로 알고 있음<br> 1로 바꾸고</p><p>ssd 파티션 1로 바꾸기</p><p>nand channel<br> lunspernand ch<br> 채널 1로 수정정</p><p>추가적으로 바꿀건 없는 것 같다.</p><p>LSB, MSB, CSB<br> NAND 셀은 1비트 저장한다고 설명. -&gt; 근데 요즘은 늘려뒀음 기본 3bit 저장</p><p>셀마다 저장하는 bit가 늘어나면 그 page가 늘어난?다고?</p><p>MLC는 하나의 셀에서 2개의 비트 저장<br> TLC는 트리플<br> 4bit는 쿼드<br> 이런게 있다 정도만 이해..</p><p>아마 파일을 공유해주실듯</p><p>컴퓨터 하나에서 하나밖에 실험이 안됨<br> 다른분들 계심. 이미 실험중이면 제한될 수 있음</p><p>lsmod | grep nvmev 써서 돌아가는지 확인 할 수 있음..</p><p>디렉토리가서 makefile있는데<br> make clean<br> make 치면 된다<br> 치기전에 kbuild 주석 처리 하면 make만 치면됨</p><p>/insmod.sh</p><p>.k파일 있으면 커널 페이지를 인스톨<br> 가사에 ssd가 os에서 인시</p><p>fdisk -l 쓰면 도니다</p><p>물리적으로 끼워진걸로 인식된 상태</p><p>디바이스를 끼우면<br> mount써서 커미팅 하고?<br> 파일 시스템에 붙혀서<br> mnt디렉토리 만들어서</p><p>마운트 됐으면 sudo df -h</p><p>![[df_output_tmpfs_example.png]]</p><p>nvme1n1확인 해야한다</p><p>fdisk이런거 써서</p><p>nvme가 0n1이런거는 실험전에 꼭 확인</p><p>m1디바이스 전부 초기화 해야할 수도 있음</p><p>인스톨 벌트 하면 다 돌아가는 상태</p><p>실험 끝나면 umount.sh<br> rmmod.sh</p>",43)])])}const _=r(t,[["render",a]]);export{l as __pageData,_ as default};
